  "claim": {
    "component_id": "C034.component",
    "value": "An improvement in useful first publication under random assignment would support deploying that change for comparable accounts.",
    "scope": "Conditional deployment support for comparable accounts; actual adoption additionally requires meeting predefined benefit, precision and guardrail criteria.",
    "provenance": {
      "refs": [
        {
          "source_id": "P025",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P025 supplies the deployment-support claim, and P027 supplies the additional adoption restrictions."
    }
  },
  "signal_basis": {
    "component_id": "C034.signal_basis",
    "value": "A favorable difference in first-publication rates between randomly assigned change and current-experience accounts, assessed alongside uncertainty, guardrails and intermediate behavior.",
    "scope": "Eligible new accounts over predefined follow-up spanning an intended roster opportunity, with specified worthwhile-benefit and precision requirements and guardrails including unusable publications.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply random assignment, the measurement and decision conditions, and the observed publication-rate comparison."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C034.stated_empirical_relation",
    "value": "First publication represents useful activation; the mapping explicitly treats this relationship as provisional and calls for checking whether interviewed accounts intended to publish.",
    "scope": "The observed customer types and follow-up period.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P037",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P005 explicitly states the unresolved publication-to-useful-activation relationship; P037 bounds generalization."
    }
  },
  "rationale": "Random assignment licenses causal interpretation of an improvement in measured publication, but does not establish that publication represents useful activation. P005 supplies that specific unresolved empirical link. Establishing it would license the claimed deployment support within the stated bounds and adoption criteria.",
  "uncertainty": "The packet does not establish the provisional usefulness relationship. Publication gains and acceptable guardrails alone do not settle it.",
  "anomalies": []
}
